function bit<16> checksum(headers_t h) {
    bit<32> sum = 0;
    switch (h.type()) {
        case ipv4_t:
            sum = ipv4_checksum(h.ipv4_);
            break;
        case tcp_t:
            sum = tcp_checksum(h.tcp_);
            break;
        case udp_t:
            sum = udp_checksum(h.udp_);
            break;
        default:
            error("Unsupported header type for checksum calculation");
    }
    return (bit<16>)sum;
}

function bit<32> ipv4_checksum(IPv4Header h) {
    bit<16> *data = (bit<16> *)&h;
    bit<16> *data_end = (bit<16> *)(&h + 1);
    bit<32> sum = 0;
    while (data < data_end) {
        sum += *data++;
    }
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return ~sum;
}

function bit<32> tcp_checksum(TCPHeader h) {
    bit<32> sum = 0;
    sum += h.srcPort;
    sum += h.dstPort;
    sum += h.seqNum;
    sum += h.ackNum;
    sum += h.window;
    sum += h.urgentPtr;
    return checksum_data((bit<8> *)&h, sizeof(TCPHeader));
}

function bit<32> udp_checksum(UDPHeader h) {
    bit<32> sum = 0;
    sum += h.srcPort;
    sum += h.dstPort;
    sum += h.length;
    return checksum_data((bit<8> *)&h, sizeof(UDPHeader));
}

function bit<32> checksum_data(bit<8> *data, int len) {
    bit<32> sum = 0;
    while (len > 1) {
        sum += *(bit<16> *)data;
        data += 2;
        len -= 2;
    }
    if (len > 0) {
        sum += *(bit<8> *)data;
    }
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return ~sum;
}
